window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aeda673208b7b668"]={"versions": [{"id": "FIG-aeda673208b7b668", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Klassifikationsbaum / Taxonomie-Diagramm zur Funktions- und Dienststruktur des AUTOSAR Classic Platform DIO-Treibers (Microcontroller Abstraction Layer, MCAL). Das Diagramm gliedert die Basisfunktionalitäten des Treibers hierarchisch nach Zugriffsart und adressierter Abstraktionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Wurzel bildet der Gesamtdienstkomplex <code>DIO service</code>. Dieser verzweigt auf der ersten Ebene in zwei Zugriffsarten:</p>\n<ul class=\"fig-list\"><li><code>read</code> (lesender Zugriff)\n</li><li><code>write</code> (schreibender Zugriff)\n</li></ul>\n<p class=\"fig-p\">Jede der beiden Zugriffsarten fächert auf der zweiten Ebene in dieselben drei Zielentitäten bzw. Granularitätsstufen auf:</p>\n<ul class=\"fig-list\"><li><code>port</code>: Adressierung eines vollständigen Hardware-DIO-Ports (Verbund mehrerer Pins).\n</li><li><code>channel</code>: Adressierung eines einzelnen diskreten DIO-Pins/Kanals.\n</li><li><code>channel group</code>: Adressierung einer zusammenhängenden Teilmenge von Pins innerhalb eines Ports, definiert über Maskierung und Offset.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Klassifikationsbaum ohne zeitliche Dynamik, Kontrollflüsse oder Nachrichtensequenzen. Die Verzweigungskanten repräsentieren logische Spezialisierungs- bzw. Zuordnungsbeziehungen: Ein Aufruf an den DIO-Dienst bestimmt sich orthogonal aus der auszuführenden Operation (<code>read</code> oder <code>write</code>) und der Granularität des Zielobjekts (<code>channel</code>, <code>port</code> oder <code>channel group</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert die strukturelle Vollständigkeit der standardisierten Kernschnittstellen des DIO-Treibers. Daraus leiten sich direkt die sechs synchronen Standard-C-APIs ab:</p>\n<ul class=\"fig-list\"><li><code>Dio_ReadChannel</code> / <code>Dio_WriteChannel</code>\n</li><li><code>Dio_ReadPort</code> / <code>Dio_WritePort</code>\n</li><li><code>Dio_ReadChannelGroup</code> / <code>Dio_WriteChannelGroup</code>\n</li></ul>\n<p class=\"fig-p\">Für Entwickler verdeutlicht die Struktur, dass alle drei Zielabstraktionen sowohl lesend als auch schreibend ohne asynchrone Zwischenzustände unterstützt werden müssen.</p>"}, {"id": "FIG-66866e0c43f067f2", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Klassifikationsbaum / Taxonomie-Diagramm zur Funktions- und Dienststruktur des AUTOSAR Classic Platform DIO-Treibers (Microcontroller Abstraction Layer, MCAL). Das Diagramm gliedert die Basisfunktionalitäten des Treibers hierarchisch nach Zugriffsart und adressierter Abstraktionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Wurzel bildet der Gesamtdienstkomplex <code>DIO service</code>. Dieser verzweigt auf der ersten Ebene in zwei Zugriffsarten:</p>\n<ul class=\"fig-list\"><li><code>read</code> (lesender Zugriff)\n</li><li><code>write</code> (schreibender Zugriff)\n</li></ul>\n<p class=\"fig-p\">Jede der beiden Zugriffsarten fächert auf der zweiten Ebene in dieselben drei Zielentitäten bzw. Granularitätsstufen auf:</p>\n<ul class=\"fig-list\"><li><code>port</code>: Adressierung eines vollständigen Hardware-DIO-Ports (Verbund mehrerer Pins).\n</li><li><code>channel</code>: Adressierung eines einzelnen diskreten DIO-Pins/Kanals.\n</li><li><code>channel group</code>: Adressierung einer zusammenhängenden Teilmenge von Pins innerhalb eines Ports, definiert über Maskierung und Offset.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Klassifikationsbaum ohne zeitliche Dynamik, Kontrollflüsse oder Nachrichtensequenzen. Die Verzweigungskanten repräsentieren logische Spezialisierungs- bzw. Zuordnungsbeziehungen: Ein Aufruf an den DIO-Dienst bestimmt sich orthogonal aus der auszuführenden Operation (<code>read</code> oder <code>write</code>) und der Granularität des Zielobjekts (<code>channel</code>, <code>port</code> oder <code>channel group</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert die strukturelle Vollständigkeit der standardisierten Kernschnittstellen des DIO-Treibers. Daraus leiten sich direkt die sechs synchronen Standard-C-APIs ab:</p>\n<ul class=\"fig-list\"><li><code>Dio_ReadChannel</code> / <code>Dio_WriteChannel</code>\n</li><li><code>Dio_ReadPort</code> / <code>Dio_WritePort</code>\n</li><li><code>Dio_ReadChannelGroup</code> / <code>Dio_WriteChannelGroup</code>\n</li></ul>\n<p class=\"fig-p\">Für Entwickler verdeutlicht die Struktur, dass alle drei Zielabstraktionen sowohl lesend als auch schreibend ohne asynchrone Zwischenzustände unterstützt werden müssen.</p>"}, {"id": "FIG-d76509849c8f06b3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Klassifikationsbaum / Taxonomie-Diagramm zur Funktions- und Dienststruktur des AUTOSAR Classic Platform DIO-Treibers (Microcontroller Abstraction Layer, MCAL). Das Diagramm gliedert die Basisfunktionalitäten des Treibers hierarchisch nach Zugriffsart und adressierter Abstraktionsebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Wurzel bildet der Gesamtdienstkomplex <code>DIO service</code>. Dieser verzweigt auf der ersten Ebene in zwei Zugriffsarten:</p>\n<ul class=\"fig-list\"><li><code>read</code> (lesender Zugriff)\n</li><li><code>write</code> (schreibender Zugriff)\n</li></ul>\n<p class=\"fig-p\">Jede der beiden Zugriffsarten fächert auf der zweiten Ebene in dieselben drei Zielentitäten bzw. Granularitätsstufen auf:</p>\n<ul class=\"fig-list\"><li><code>port</code>: Adressierung eines vollständigen Hardware-DIO-Ports (Verbund mehrerer Pins).\n</li><li><code>channel</code>: Adressierung eines einzelnen diskreten DIO-Pins/Kanals.\n</li><li><code>channel group</code>: Adressierung einer zusammenhängenden Teilmenge von Pins innerhalb eines Ports, definiert über Maskierung und Offset.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statischer Klassifikationsbaum ohne zeitliche Dynamik, Kontrollflüsse oder Nachrichtensequenzen. Die Verzweigungskanten repräsentieren logische Spezialisierungs- bzw. Zuordnungsbeziehungen: Ein Aufruf an den DIO-Dienst bestimmt sich orthogonal aus der auszuführenden Operation (<code>read</code> oder <code>write</code>) und der Granularität des Zielobjekts (<code>channel</code>, <code>port</code> oder <code>channel group</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild definiert die strukturelle Vollständigkeit der standardisierten Kernschnittstellen des DIO-Treibers. Daraus leiten sich direkt die sechs synchronen Standard-C-APIs ab:</p>\n<ul class=\"fig-list\"><li><code>Dio_ReadChannel</code> / <code>Dio_WriteChannel</code>\n</li><li><code>Dio_ReadPort</code> / <code>Dio_WritePort</code>\n</li><li><code>Dio_ReadChannelGroup</code> / <code>Dio_WriteChannelGroup</code>\n</li></ul>\n<p class=\"fig-p\">Für Entwickler verdeutlicht die Struktur, dass alle drei Zielabstraktionen sowohl lesend als auch schreibend ohne asynchrone Zwischenzustände unterstützt werden müssen.</p>"}], "trans": [{"from": "FIG-aeda673208b7b668", "to": "FIG-66866e0c43f067f2", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-66866e0c43f067f2", "to": "FIG-d76509849c8f06b3", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
